<?php

declare(strict_types=1);

namespace Modules\Sample\Widgets;

use Illuminate\Contracts\Auth\Authenticatable;
use Modules\Sample\Models\Sample;
use Yuan\AdminCore\Dashboard\DashboardRange;
use Yuan\AdminCore\Dashboard\Widget;
use Yuan\AdminCore\Dashboard\WidgetSize;
use Yuan\AdminCore\Dashboard\WidgetType;
use Yuan\AdminCore\Data\Widgets\StatWidgetData;

/** Jumlah baru: contoh created in the range (generated by make:widget). */
final class JumlahBaru extends Widget
{
    public function key(): string
    {
        return 'samples.jumlah_baru';
    }

    public function label(): string
    {
        return 'Jumlah baru';
    }

    public function type(): WidgetType
    {
        return WidgetType::Stat;
    }

    public function size(): WidgetSize
    {
        return WidgetSize::Sm;
    }

    public function data(Authenticatable $user, DashboardRange $range): StatWidgetData
    {
        return new StatWidgetData(
            value: Sample::query()->visibleTo($user)->whereBetween('created_at', [$range->from, $range->to])->count(),
            icon: 'flask-conical',
        );
    }
}
